INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-13-z12-q81','nism-13-z12','Spot price is ₹3800, financing rate 7% p.a., expected dividend ₹0 during the period, and futures expiry in 60 days. The fair futures price is:','["₹4,066.00","₹3,848.73","₹3,800.00","₹3,843.73"]',3,'F = S[1 + r·t/365] − D = ₹3,843.73.',81) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort WHERE questions.quiz_id IS NOT excluded.quiz_id OR questions.question IS NOT excluded.question OR questions.options IS NOT excluded.options OR questions.answer IS NOT excluded.answer OR questions.explanation IS NOT excluded.explanation OR questions.sort IS NOT excluded.sort;
